def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    N = 1 << n
    if L >= N:
        for i in range(n):
            qc.h(i)
        return qc

    def recurse(pref, bit_idx):
        if bit_idx < 0:
            return
        total = 1 << (bit_idx + 1)
        low = pref
        high = low + total
        cnt = min(L, high) - low
        if cnt <= 0:
            return
        left_high = low + (1 << bit_idx)
        c0 = min(L, left_high) - low
        if c0 < 0:
            c0 = 0
        c1 = cnt - c0

        if c0 == 0:
            theta = math.pi
        elif c1 == 0:
            theta = 0.0
        else:
            p0 = c0 / cnt
            p0 = max(0.0, min(1.0, p0))
            theta = 2.0 * math.acos(math.sqrt(p0))

        controls = list(range(bit_idx + 1, n))
        for j in controls:
            if ((pref >> j) & 1) == 0:
                qc.x(j)

        if controls:
            gate = MCRYGate(theta, len(controls))
            qc.append(gate, controls + [bit_idx])
        else:
            qc.ry(theta, bit_idx)

        for j in controls:
            if ((pref >> j) & 1) == 0:
                qc.x(j)

        # left child  bit = 0
        recurse(pref, bit_idx - 1)
        # right child bit = 1
        pref_right = pref | (1 << bit_idx)
        recurse(pref_right, bit_idx - 1)

    recurse(0, n - 1)
    return qc

