def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    for i in range(n):
        qc.h(i)

    N = 1 << n
    M = L
    if M >= N:
        return qc
    if M / N > 0.5:
        return qc

    theta = math.asin(math.sqrt(M / N))
    k = 0
    # smallest k with sin^2((2k+1)theta) > 0.5
    while True:
        prob = math.sin((2 * k + 1) * theta) ** 2
        if prob > 0.5:
            break
        k += 1
        if k > 500:          # safety
            break

    # multi-controlled Z = MCPhase(pi, n-1)
    if n == 1:
        phase = None
    else:
        phase = MCPhaseGate(math.pi, n - 1)

    def apply_phase():
        if n == 1:
            qc.z(0)
        else:
            qc.append(phase, range(n))

    for _ in range(k):
        # oracle : mark |i> , i < L
        for i in range(M):
            for j in range(n):
                if ((i >> j) & 1) == 0:
                    qc.x(j)
            apply_phase()
            for j in range(n):
                if ((i >> j) & 1) == 0:
                    qc.x(j)

        # diffusion
        for i in range(n):
            qc.h(i)
        for i in range(n):
            qc.x(i)
        apply_phase()
        for i in range(n):
            qc.x(i)
        for i in range(n):
            qc.h(i)

    return qc

