def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    if L <= 0:
        return qc
    N = 1 << n
    if L >= N:
        for i in range(n):
            qc.h(i)
        return qc

    # recursive multiplexed Ry preparation for the first L states
    for k in range(n - 1, -1, -1):
        step = 1 << (k + 1)
        # bases are multiples of step
        for base in range(0, N, step):
            if base >= L:
                continue
            end = base + step
            if end > N:
                end = N
            total = min(end, L) - base
            if total <= 0:
                continue
            mid = base + (1 << k)
            count_low = max(0, min(mid, L) - base)
            count_high = total - count_low
            if count_high == 0:
                continue
            ratio = count_high / total
            ratio = max(0.0, min(1.0, ratio))
            theta = 2.0 * math.asin(math.sqrt(ratio))

            controls = list(range(k + 1, n))
            if not controls:
                qc.ry(theta, k)
            else:
                ctrl_state = ''.join('1' if (base >> c) & 1 else '0' for c in controls)
                qc.mcry(theta, controls, k, ctrl_state=ctrl_state)
    return qc

