def solve(n: int, L: int, theta: float) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    if theta == 0.0:
        return qc

    size = 1 << n
    factor = -2.0 * theta / size          # angle = factor * sign

    for k in range(1, size):
        # sign = (-1)^{popcount(L & k)}
        parity = bin(L & k).count("1") & 1
        sign = -1.0 if parity else 1.0
        angle = factor * sign

        # qubits where k has a 1, little endian
        qubits = [i for i in range(n) if (k >> i) & 1]
        if not qubits:
            continue
        target = qubits[0]
        for ctrl in qubits[1:]:
            qc.cx(ctrl, target)
        qc.rz(angle, target)
        for ctrl in qubits[1:]:
            qc.cx(ctrl, target)

    return qc

