    qc = QuantumCircuit(n)
    # QFT for little-endian qubits, LSB = qubit 0
    for i in range(n):
        qc.h(i)
        for j in range(i + 1, n):
            # R_{j-i+1} = diag(1,1,1,exp(2πi/2^{j-i+1}))
            angle = math.pi / (2 ** (j - i))   # = 2π / 2^{j-i+1}
            qc.cp(angle, j, i)                 # control j, target i
    # final reversal
    for i in range(n // 2):
        qc.swap(i, n - 1 - i)
    return qc

