def solve(n: int, o: QuantumCircuit) -> QuantumCircuit:
    x = QuantumRegister(n)
    y = QuantumRegister(1)
    qc = QuantumCircuit(x, y)

    # extract L from the depth-1 oracle
    # the oracle is assumed to act on n+1 qubits, the last one is the ancilla
    L = 0
    if len(o.qubits) == n + 1:
        target = o.qubits[-1]
        q_to_idx = {q: i for i, q in enumerate(o.qubits)}
        found = False
        for inst in o.data:
            if target in inst.qubits:
                op = inst.operation
                # a multi-controlled X is the only gate that touches the ancilla
                if op.name.lower() in ("mcx", "mcx", "cx", "x", "mcx"):
                    controls = [q for q in inst.qubits if q is not target]
                    ctrl_state = getattr(op, "ctrl_state", None)
                    if ctrl_state is None:
                        bits = ["1"] * len(controls)
                    else:
                        if isinstance(ctrl_state, str):
                            bits = list(ctrl_state)
                        else:
                            # int -> binary, little endian for the control list
                            s = bin(int(ctrl_state))[2:].zfill(len(controls))
                            bits = list(s[::-1])
                    L_val = 0
                    for q, b in zip(controls, bits):
                        idx = q_to_idx.get(q)
                        if idx is None:
                            continue
                        if b == "1":
                            L_val |= 1 << idx
                    L = L_val
                    found = True
                    break
        if not found:
            # fallback – the oracle is a permutation, the marked basis state is
            # the only one that maps |x>|0> -> |x>|1>
            from qiskit.quantum_info import Operator
            U = Operator(o).data
            offset = 1 << n
            for xv in range(1 << n):
                if abs(U[xv + offset, xv]) > 0.5:
                    L = xv
                    break

    for i in range(n):
        if (L >> i) & 1:
            qc.x(x[i])
    # y stays |0>
    return qc

