from qiskit.circuit.library import PermutationGate


def solve(n: int, s: int, t: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    bits = n + 1
    N = 1 << bits
    half = 1 << n

    # little endian mapping required by the statement
    mapping = {}
    for k in range(s, half):
        mapping[k] = k - s
    for k in range(half, t):
        mapping[k] = k + N - t

    used_dom = set(mapping.keys())
    used_img = set(mapping.values())

    def rev(i: int) -> int:
        r = 0
        for _ in range(bits):
            r = (r << 1) | (i & 1)
            i >>= 1
        return r

    perm = [0] * N
    # place the required part in reversed index space
    for k, img in mapping.items():
        perm[rev(k)] = rev(img)

    used_rev_dom = {rev(k) for k in used_dom}
    used_rev_img = {rev(v) for v in used_img}

    remaining_dom = [i for i in range(N) if i not in used_rev_dom]
    remaining_img = [i for i in range(N) if i not in used_rev_img]

    for d, im in zip(remaining_dom, remaining_img):
        perm[d] = im

    qc.append(PermutationGate(perm), range(n + 1))
    return qc

