def solve(n: int, m: int, a: int, L: int) -> QuantumCircuit:
    x = QuantumRegister(n)
    y = QuantumRegister(2 * m + 1)
    qc = QuantumCircuit(x, y)

    # uniform superposition on the exponent register
    for i in range(n):
        qc.h(x[i])

    # |k>|0> -> |k>|a^k mod L>
    for k in range(1 << n):
        v = pow(a, k, L)
        # flip controls so that the pattern is all-ones
        for i in range(n):
            if ((k >> i) & 1) == 0:
                qc.x(x[i])

        for j in range(2 * m + 1):
            if (v >> j) & 1:
                qc.mcx(x, y[j])          # controlled by x == k

        # restore controls
        for i in range(n):
            if ((k >> i) & 1) == 0:
                qc.x(x[i])

    return qc

